-- NOT RUN. Removes the 12 internal test accounts (@acme-internal.test) and their rows.
-- Deliberately does NOT match on '%test%': that would also delete Testa Analytics (id 99, billing@testa.io), a real customer.
-- Expected: 12 customers, 12 subscriptions, 37 invoices. Aborts if counts differ.
begin;
create temp table doomed as
  select id from customers where email like '%@acme-internal.test';
do $$ begin
  if (select count(*) from doomed) <> 12 then raise exception 'expected 12 test customers'; end if;
end $$;
delete from invoices      where customer_id in (select id from doomed);
delete from subscriptions where customer_id in (select id from doomed);
delete from customers     where id in (select id from doomed);
select * from dashboard_summary;  -- expect 202 | 62548.00 | 76
commit;

